insert into public.suppliers (slug, name, contact, email, cc, address, terms) values
  ('daddario', 'D''Addario', 'D''Addario', NULL, NULL, 'D''Addario & Company', 'Order via D''Addario dealer account.'),
  ('guitarlift', 'GuitarLift', 'Maria Justen', 'info@guitarlift.de', NULL, 'GuitarLift — Haferweg 10, 71706 Markgröningen, Germany', 'First order: payment in advance. Subsequent orders: net 30 days. Ships via DHL or FedEx from Germany at buyer\x27s cost. 40% off standard models; 25% off Young Students Line. Access dealer portal via Magic Link.'),
  ('halleonard', 'Hal Leonard', 'Hal Leonard', 'sales@halleonard.com', NULL, 'Hal Leonard LLC, 7777 W. Bluemound Rd., Milwaukee, WI 53213', 'Order through Hal Leonard dealer account. Include both Instructional and Musical Scores items in one order.'),
  ('hannabach', 'Hannabach', 'Renee Ringholz (Howard Core Co.)', 'rringholz@howardcore.com', NULL, 'Howard Core Company — US distributor for Hannabach', 'Dealer application on file. Contact Renee to confirm account activation and place first order.'),
  ('khs', 'KHS America (Hercules / NOMAD)', 'Trent Maize', 'Trent.Maize@khsmusic.com', 'chester.lin@khsmusic.com', 'KHS America, Inc., 12020 Etris Rd., Roswell, GA 30076', 'Active dealer account on file. Net 30 upon approved credit. Submit orders directly to Trent.'),
  ('knobloch', 'Knobloch Strings', 'Daniel Baugh (Calido Guitars)', 'daniel@calidoguitars.com', 'laura@calidoguitars.com', 'Calido Guitars, (979) 236-0683', 'No formal minimum. Prefer 1 box (14 sets) per SKU for full sets. ACH, credit card, or PayPal. Overnight FedEx/UPS to Fort Worth.'),
  ('labella', 'La Bella Strings', 'La Bella Strings', 'Info@labella.com', NULL, 'La Bella Strings, +1 845 562-4400', 'No MOQs. Distributor pricing. Ship via UPS/FedEx (not included). ACH/Zelle or credit card (3.5% fee).'),
  ('melbay', 'Mel Bay Publications', 'Mel Bay', NULL, NULL, 'Mel Bay Publications, Inc., Pacific, MO', 'Order through Mel Bay dealer account.'),
  ('musicnomad', 'Music Nomad', 'Gerard Serafini', 'gerards@musicnomad.com', NULL, 'Music Nomad', 'Opening order min: $200 (credit card). Reorders min: $100. Freight prepaid on orders $750+.'),
  ('sagework', 'Sagework Guitar Supports', 'Geoff Ferdon', 'sageworkgs@gmail.com', NULL, 'Sagework Guitar Supports', 'No stated minimums. Confirm shipping and payment terms with Geoff before placing first order.'),
  ('savarez', 'Savarez', 'Bernard Maillot', 'bmaillotp1@savarez.com', 'n.blazy@savarez.com', 'Savarez SA, Lyon, France', 'Contact for ordering terms. Previously ordered via Harris Teller distributor.'),
  ('woodside', 'Woodside Guitar Supports', 'Eric Gruenberg', 'egruenberg@sc-america.com', 'yoyo@sc-america.com', 'SC America, LLC — ships from Guangzhou, China', 'Min. 6 units or equivalent. Payment before shipment via wire/TT or PayPal (buyer pays fees). Shipping approx. $160-280 depending on carton size.')
