-- ---- Suppliers --------------------------------------------------
on conflict (slug) do update set
  name=excluded.name, contact=excluded.contact, email=excluded.email,
  cc=excluded.cc, address=excluded.address, terms=excluded.terms;

-- ---- Brands -----------------------------------------------------
on conflict (slug) do update set
  name=excluded.name, brand_type=excluded.brand_type, category=excluded.category,
  subcategory=excluded.subcategory, supplier_id=excluded.supplier_id,
  moq_amount=excluded.moq_amount, moq_label=excluded.moq_label, sort_order=excluded.sort_order;

-- ---- Products ---------------------------------------------------
on conflict (brand_id, sku) do update set
  description=excluded.description, retail=excluded.retail, dealer_cost=excluded.dealer_cost,
  pack_type=excluded.pack_type, tension=excluded.tension, group_label=excluded.group_label,
  subgroup_label=excluded.subgroup_label, sort_order=excluded.sort_order, active=true;

